1126	      if (Kind == Action::OFK_Cuda) {
1127	        auto &CudaInstallation =
1128	            static_cast<const toolchains::CudaToolChain &>(TC).CudaInstallation;
1129	        if (CudaInstallation.isValid())
1130	          CudaInstallation.WarnIfUnsupportedVersion();
